class Solution {
public:
    int findShortestSubArray(vector<int>& nums) {
        map<int, int> cnt, first;
        int degree = 0, best = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            int x = nums[i];
            if (!first.count(x)) first[x] = i;
            int c = ++cnt[x];
            int span = i - first[x] + 1;
            if (c > degree) {
                degree = c;
                best = span;
            } else if (c == degree) {
                best = min(best, span);
            }
        }
        return best;
    }
};
